contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Acts as: access controller (checkAccess -> true), and vault (utilization / currentUtilizationIndex -> 0)
    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encode(uint256(0));
    }

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        require(kink > 0 && kink < 1e27);
        require(slope0 <= 1e30 && slope1 <= 1e30);

        c.initialize(address(this));
        IVaultAdapter.SlopeData memory slopes;
        slopes.kink = kink;
        slopes.slope0 = slope0;
        slopes.slope1 = slope1;
        c.setSlopes(asset, slopes);
        c.setLimits(1e27, 1e27, 1);

        uint256 r = c.rate(address(this), asset);
        assert(r == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; c.initialize(address(this)); }
    function run(uint256 kink, uint256 slope0, uint256 slope1) public {
        require(kink < 1e30 && slope0 < 1e30 && slope1 < 1e30);
        bool reverted;
        try c.setSlopes(address(0x1), IVaultAdapter.SlopeData(kink, slope0, slope1)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted == (kink == 0 || kink >= 1e27));
    }
    fallback(bytes calldata) external payable returns (bytes memory) {
        if (msg.sig == IAccessControl.checkAccess.selector) {
            return abi.encode(true);
        }
        return "";
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _asset) public {
        require(uint256(_asset) != 0);
        // c is fresh: utilizationData.lastUpdate == 0, so elapsed == block.timestamp
        // and rate() reads utilization(_asset) directly from the "vault" (this contract).
        // With default slopes (kink == 0), any nonzero utilization takes the kink-excess
        // branch; with default rate == 0 the multiplier stays unchanged and, since
        // slope0 == slope1 == 0, the resulting interest rate must be 0.
        uint256 r = c.rate(address(this), _asset);
        assert(r == 0);
    }

    fallback() external payable {
        bytes4 sel;
        assembly {
            sel := shr(224, calldataload(0))
        }
        if (sel == bytes4(keccak256("utilization(address)"))) {
            uint256 util;
            assembly {
                util := calldataload(36)
            }
            assembly {
                mstore(0, util)
                return(0, 32)
            }
        }
        // currentUtilizationIndex should not be reached on the first rate() call
        assembly {
            mstore(0, 0)
            return(0, 32)
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _asset, uint256 _util) public {
        require(_asset != address(0));
        require(_util != 0);
        // c is fresh: utilizationData.lastUpdate == 0, so elapsed == block.timestamp
        // and rate() reads utilization(_asset) directly from the "vault" (this contract).
        // With default slopes (kink == 0), any nonzero utilization takes the kink-excess
        // branch; with default rate == 0 the multiplier stays unchanged and, since
        // slope0 == slope1 == 0, the resulting interest rate must be 0.
        uint256 r = c.rate(address(this), _asset);
        assert(r == 0);
    }

    fallback() external payable {
        bytes4 sel;
        assembly {
            sel := shr(224, calldataload(0))
        }
        if (sel == bytes4(keccak256("utilization(address)"))) {
            assembly {
                mstore(0, 1)
                return(0, 32)
            }
        }
        assembly {
            mstore(0, 0)
            return(0, 32)
        }
    }

    receive() external payable {}
}

